#pragma once
#include "ksScheduledTimerCoordinator.h"
#include "ksStateCentralActionsService.h"
#include "ksStateStatusService.h"
#include "ksStateProgramBrowserService.h"
#include <variant>
namespace ks {
// All five delayed-action slots and every authenticated ordinary callback.
// A timer stores data handles. Only the fixed typed action chooses a child.
class ScheduledTimerService final {
public:
 using Coordinator=ScheduledTimerCoordinator;using Kind=Coordinator::Kind;using Action=Coordinator::Action;using Effect=Coordinator::Effect;
 enum class Component{Timer,Field,Notice,Actions,Browser,Status};
 struct Input{uint16_t delay=0;Action action=Action::FieldClear;ScheduledTimerTask::ActionHandle storageAction{};};
 struct Summary{bool fired=false,callbackCompleted=false;Action action=Action::FieldClear;uint32_t callbackWord=0;unsigned callbackReturns=0;};
 struct Notice{StateBankNavigationTask task{StateBankNavigationTask::Kind::ClearNotice};std::optional<StateFieldService>ui;uint16_t presentation=0;bool inUi=false;explicit Notice(uint16_t value):presentation(value){}bool complete()const{return task.complete();}};
 using Child=std::variant<std::monostate,StateFieldService,Notice,StateCentralActionsService,StateProgramBrowserService,StateStatusService>;
 ScheduledTimerService(Kind k,unsigned slot):ScheduledTimerService(k,slot,Input{}){}
 ScheduledTimerService(Kind k,unsigned slot,Input in):coordinator_(k,slot,{in.delay,in.action}),input_(in){if(k==Kind::Arm&&in.storageAction.value&&Coordinator::decode(in.storageAction.value)!=in.action)throw std::logic_error("Timer arm handle differs from typed binding");}
 Kind kind()const{return coordinator_.kind();}unsigned slot()const{return coordinator_.slot();}const Input&input()const{return input_;}const Coordinator&coordinator()const{return coordinator_;}const Child&child()const{return child_;}const Summary&summary()const{return summary_;}bool complete()const{return coordinator_.complete();}Component component()const{return component_;}uint32_t components()const{return components_;}const Effect&effect()const{return effect_;}
 unsigned priority()const{if(component_==Component::Actions)return std::get<StateCentralActionsService>(child_).priority();if(component_==Component::Field)return std::get<StateFieldService>(child_).critical()?7:0;if(component_==Component::Notice){const auto&n=std::get<Notice>(child_);return n.inUi&&n.ui->critical()?7:0;}if(component_==Component::Browser)return std::get<StateProgramBrowserService>(child_).critical()?7:0;return 0;}bool critical()const{return priority()==7;}
 bool presentationKnown()const{return complete()&&kind()==Kind::Arm;}uint16_t presentation()const{return uint16_t(coordinator_.summary().counter);}
 template<class T>const T*task()const{if(complete())return nullptr;if constexpr(std::is_same_v<T,ScheduledTimerService>)return this;else if constexpr(std::is_same_v<T,Coordinator>)return component_==Component::Timer?&coordinator_:nullptr;else{if(component_==Component::Timer)return coordinator_.template task<T>();return std::visit([&](const auto&s)->const T*{using S=std::decay_t<decltype(s)>;if constexpr(std::is_same_v<S,std::monostate>)return nullptr;else if constexpr(std::is_same_v<S,Notice>){if constexpr(std::is_same_v<T,StateBankNavigationTask>)return !s.inUi?&s.task:nullptr;else if(s.inUi)return fieldTask<T>(*s.ui);else return nullptr;}else if constexpr(std::is_same_v<S,StateFieldService>)return fieldTask<T>(s);else if constexpr(std::is_same_v<T,S>)return &s;else return s.template task<T>();},child_);}}
 unsigned nextClocks(int previous=-1)const{if(complete())return 0;if(component_==Component::Timer)return coordinator_.nextClocks(previous);return std::visit([&](const auto&s)->unsigned{using S=std::decay_t<decltype(s)>;if constexpr(std::is_same_v<S,std::monostate>)return 0;else if constexpr(std::is_same_v<S,Notice>)return s.inUi?s.ui->nextClocks(previous):s.task.nextClocks(byteClock(0x16791,previous));else return s.nextClocks(previous);},child_);}
 template<class R,class W,class Resolver>unsigned advanceBefore(unsigned budget,R&&rawRead,W&&rawWrite,Resolver&&resolver,int previous=-1){const auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;effect_={};const auto read=[&](uint32_t raw,unsigned dt){const auto a=raw&0xffffff;if(!readEndpoint(a))throw std::logic_error("Unsupported evolving timer read endpoint");return rawRead(a,dt);};const auto write=[&](uint32_t raw,uint8_t value,unsigned dt){const auto a=raw&0xffffff;if(!writeEndpoint(a))throw std::logic_error("Unsupported evolving timer write endpoint");rawWrite(a,value,dt);};
 if(component_==Component::Timer){coordinator_.advanceBefore(cost,read,write,previous,input_.storageAction);effect_=coordinator_.effect();if(coordinator_.awaitingAction())dispatch();return cost;}
 bool done=false;std::visit([&](auto&s){using S=std::decay_t<decltype(s)>;if constexpr(std::is_same_v<S,std::monostate>)throw std::logic_error("Timer callback missing owner");else if constexpr(std::is_same_v<S,Notice>){if(s.inUi){s.ui->advanceBefore(cost,read,write,resolver,previous);effect_={s.ui->effect().read,s.ui->effect().write};if(s.ui->complete()){s.task.resumeChild(0);s.inUi=false;}}else{const auto stage=s.task.stage();s.task.advanceBefore(cost,[](auto,uint32_t)->uint32_t{throw std::logic_error("Unexpected notice clear read");},[&](auto,uint32_t,uint32_t v){write(0x16791,uint8_t(v),cost);},byteClock(0x16791,previous));effect_.write=stage==StateBankNavigationTask::Stage::RefreshNotice;effect_.read=stage==StateBankNavigationTask::Stage::ReturnClearedNotice;if(s.task.awaitingChild()){s.ui.emplace(StateUiRefreshService::Kind::Refresh,StateUiRefreshService::Input{0,s.presentation,s.presentation});s.inUi=true;}}done=s.complete();}else if constexpr(std::is_same_v<S,StateStatusService>){s.advanceBefore(cost,read,write,previous);effect_={s.effect().read,s.effect().write};done=s.complete();}else{s.advanceBefore(cost,read,write,resolver,previous);effect_={s.effect().read,s.effect().write};done=s.complete();if constexpr(std::is_same_v<S,StateCentralActionsService>)if(s.request()!=StateCentralActionsService::Request::None)throw std::logic_error("Unexpected external operation in fixed timer repeat callback");}},child_);
 if(done){summary_.callbackCompleted=true;++summary_.callbackReturns;if(!coordinator_.resumeAction(1))throw std::logic_error("Timer callback return differs");select(Component::Timer);}return cost;}
private:
 template<class T>static const T*fieldTask(const StateFieldService&s){if constexpr(std::is_same_v<T,StateFieldService>)return &s;else if constexpr(std::is_same_v<T,StateFieldCoordinator>||std::is_same_v<T,StateApplyService>||std::is_same_v<T,StateDisplayService>||std::is_same_v<T,StateScreenService>||std::is_same_v<T,StateUiRefreshService>||std::is_same_v<T,StateStoreService>||std::is_same_v<T,StateFieldPacketService>||std::is_same_v<T,PanelSettingsLcdService>||std::is_same_v<T,StateSceneCoordinator>||std::is_same_v<T,StateSceneEditCoordinator>||std::is_same_v<T,StateVoiceRefreshService>)return s.template task<T>();else return nullptr;}
 static unsigned byteClock(uint32_t a,int previous){return !(previous&1)&&a==(uint32_t(previous)|1u)?0:3;}
 static bool readEndpoint(uint32_t a){return StateStoreService::dataSpan(a,1)||(a>=0x1b0&&a<0x1bc)||(a>=0x1c0&&a<0x300)||(a>=0x2a0c&&a<0x2a18)||(a>=0x800000&&a<0x900000)||(a>=0x400000&&a<0x400010)||(a>=0x600000&&a<0x600010)||a==0xffff50||a==0xffff51||a==0xffff53||a==0xffff61||a==0xffff62||a==0xfffeb1||(a>=0xffff80&&a<0xffffa0)||(a>=0xffffa4&&a<=0xffffa6)||a==0xfffff6||a==0xfffff7;}
 static bool writeEndpoint(uint32_t a){return StateStoreService::dataSpan(a,1)||(a>=0x800000&&a<0x900000)||(a>=0x400000&&a<0x400010)||(a>=0x600000&&a<0x600010)||a==0xffff50||a==0xffff51||a==0xffff61||a==0xffff62||a==0xfffeb1||(a>=0xffff80&&a<0xffffa0)||(a>=0xffffa4&&a<=0xffffa6);}
 void select(Component c){component_=c;components_|=1u<<unsigned(c);}
 void dispatch(){if(!std::holds_alternative<std::monostate>(child_))throw std::logic_error("Multiple callbacks in one timer service");summary_.fired=true;summary_.action=coordinator_.action();summary_.callbackWord=coordinator_.summary().actionWord;const auto word=coordinator_.actionPresentation();using C=StateCentralActionsService;switch(summary_.action){case Action::FieldClear:{StateFieldService::Input i;i.event=word;child_.template emplace<StateFieldService>(StateFieldService::Kind::Clear,i);select(Component::Field);break;}case Action::NoticeClear:child_.template emplace<Notice>(word);select(Component::Notice);break;case Action::StatusTick:child_.template emplace<StateStatusService>(StateStatusService::Kind::Tick,StateStatusService::Input{word});select(Component::Status);break;case Action::MenuPrevious:case Action::MenuNext:case Action::OctaveDown:case Action::OctaveUp:{const auto k=summary_.action==Action::MenuPrevious?C::Kind::MenuRepeatPrevious:summary_.action==Action::MenuNext?C::Kind::MenuRepeatNext:summary_.action==Action::OctaveDown?C::Kind::RepeatDown:C::Kind::RepeatUp;child_.template emplace<C>(k,C::Input{word});select(Component::Actions);break;}case Action::BrowseSlow:case Action::BrowseStop:case Action::BrowseFast:{using B=StateProgramBrowserService;B::Input i;i.event=word;child_.template emplace<B>(summary_.action==Action::BrowseSlow?B::Kind::Slow:summary_.action==Action::BrowseStop?B::Kind::Stopped:B::Kind::Fast,i);select(Component::Browser);break;}}}
 Coordinator coordinator_;Input input_;Child child_;Component component_=Component::Timer;uint32_t components_=1;Effect effect_{};Summary summary_{};
};
}
